	return result;
}

static void set_handle(uintptr_t *handle, io_entity_t *entity) /* <=== set_handle */ 
{
	assert(handle != NULL);
	*handle = (uintptr_t)entity;
}

static int free_entity(const io_entity_t *entity) /* <=== free_entity */ 
{
	int result;
	unsigned int index = 0;
	assert(entity != NULL);

	result = find_first_entity(entity, &index);
	if (result ==  0) {
		entity_map[index] = NULL;
		--entity_count;
	}

	return result;
}

